#!/usr/bin/env bash
# Run one task test.
# Usage: ./scripts/run-test.sh <TestName> <SrcClass...>
#   example: ./scripts/run-test.sh BookTest Book
# Do not edit this file.
set -u
cd "$(dirname "$0")/.." || exit 1

if [ $# -lt 2 ]; then
    echo "Usage: ./scripts/run-test.sh <TestName> <SrcClass...>"
    exit 2
fi
TEST="$1"
shift

# What a started file must contain (comments are ignored), and which files to look at.
case "$TEST" in
    BookTest)        PATTERN='\b(isbn|title|author|year|available|printInfo|isAvailable|borrow|returnBook)\b'
                     WATCH="src/Book.java" ;;
    ProductTest)     PATTERN='\b(code|name|price|stock|category|printInfo|isInStock|sell|totalValue)\b'
                     WATCH="src/Product.java" ;;
    ConstructorTest) PATTERN='\b(Book|Product)\s*\('
                     WATCH="src/Book.java src/Product.java" ;;
    ShopTest)        PATTERN='\b(name|items|count|Shop\s*\(|addProduct|totalStockValue|findByCode|printAll|printSummary)\b'
                     WATCH="src/Shop.java" ;;
    *) echo "Unknown test: $TEST"; exit 2 ;;
esac

rm -rf out
mkdir out

if ! javac -encoding UTF-8 -d out tests/Check.java; then
    echo "tests/Check.java does not compile. Did you edit tests/?"
    exit 1
fi

# shellcheck disable=SC2086
if ! java -cp out Check --started "$PATTERN" $WATCH; then
    echo "Nothing written yet in: $WATCH"
    echo
    echo "NOT STARTED"
    exit 1
fi

FILES=""
for c in "$@"; do
    FILES="$FILES src/$c.java"
done

# shellcheck disable=SC2086
if ! ERRORS=$(javac -encoding UTF-8 -d out $FILES tests/Check.java "tests/$TEST.java" 2>&1); then
    echo "[ ] compiles"
    echo "$ERRORS" | awk '
        !shown && /error:/ { print "    " $0; shown = 1; want = ($0 ~ /cannot find symbol/); next }
        shown && want && /symbol:/ { print "    " $0; exit }'
    echo
    echo "INCOMPLETE (does not compile)"
    exit 1
fi

java -cp out "$TEST"
